proc sql; create table final2 as select distinct a.*, std(b.chg_ib_ps) as ev_chg_ib_ps, count(b.chg_ib_ps) as ev_chg_ib_ps_n
	from final1 as a left join final1b as b on a.gvkey=b.gvkey and a.fyear-5<b.fyear<=a.fyear
	group by a.gvkey, a.datadate, a.fyear;quit;
data dxbrl.interm_compa; set final2;run;
proc sql; drop table final1, final1b, final2;quit;
*****************************************;
*****************************************;
**Estimating analyst coverage from ibes;
*************************************;
proc sql; create table ibes as select distinct a.*,b.*
	from dxbrl.interm_compa as a left join dxbrl.raw_ibes as b
		on a.permno=b.permno and b.permno ne . and year(a.datadate)=year(b.fpedats) and month(a.datadate)=month(b.fpedats)
			and b.pdicity="ANN";quit;
**Dropping duplicate matches to IBES tickers based on ..
		1) smallest (best) ICLINK score
		2) (among score ties) smallest difference between IBES actual amount and Compustat actual amount;
data ibes1; set ibes; temp_ibes_diff = abs(value - epspx); months_from_fp = intck('month',datadate,statpers);run;
proc sort data=ibes1; by gvkey fyear statpers score temp_ibes_diff;
proc sort data=ibes1 nodupkey; by gvkey fyear statpers;run;
proc sql; create table dxbrl.final_aa as select gvkey, permno, fyear, max(numest) as numanalysts
	from ibes1 where -11<=months_from_fp<=0	group by gvkey, permno, fyear; quit;

proc sql; create table sample as select a.*, b.*, b.permno as permno_backup
	from dxbrl.final_10k_withxbrl as a left join dxbrl.interm_compa as b
		on a.gvkey=b.gvkey and a.gvkey ne '' and a.datadate=b.datadate and a.fyear=b.fyear;quit;
data sample; set sample; if permno ne permno_backup and permno_backup ne . then permno=permno_backup;run;
data sample; set sample; drop permno_backup;run;
	**Step 2b - Adding IBES data;
proc sql; create table sample2 as select a.*, b.* from sample as a left join dxbrl.final_aa as b
		on a.gvkey=b.gvkey and a.permno=b.permno and a.gvkey ne '' and a.fyear=b.fyear;quit;
	**Step 2c - Adding Compustat segment data;
proc sql; create table sample3 as select a.*, b.* from sample2 as a left join dxbrl.final_segments as b
		on a.gvkey=b.gvkey and a.gvkey ne '' and a.fyear=b.fyear and a.fyear ne .;quit;
	**Step 2d - Adding inst_hold data;
proc sql; create table sample4 as select a.*, b.* from sample3 as a left join dxbrl.final_inst as b
		on a.gvkey=b.gvkey and a.gvkey ne '' and a.permno=b.permno and intnx('day',a.filingdate,-100)<=b.fdate<=a.filingdate
	order by a.filingid, b.fdate desc;quit; 
proc sort data=sample4 out=sample4b nodupkey; by filingid;run;
	**Step 2e - Adding in crsp share code;
proc sql; create table sample5 as select distinct a.*, b.shrcd from sample4b as a left join dxbrl.raw_shrcd as b
		on a.permno=b.permno and b.startdt<=a.datadate<=b.enddt;quit;
	**Step 2f - Adding in prior year return volatility and abnormal returns for year through filing window;
proc sql; create table sample5b 
	as select distinct a.*, std(b.ret) as py_ret_std, exp(sum(log(1+(b.ret - b.vwretd))))-1 as py_abn_ret
	from sample5 (keep= filingid permno filingdate) as a left join 
			dxbrl.raw_crsp (keep= permno date ret vwretd dolvol vol shrout) as b
		on a.permno=b.permno and a.permno ne . and intnx('day',a.filingdate,-363) <= b.date <= intnx('day',a.filingdate,+1)
		and b.ret ne . and b.vwretd ne . and a.filingdate ne .
	group by a.filingid	order by a.filingid;quit;
proc sql; create table sample6 as select a.*, b.* from sample5b as a left join sample5 as b on a.filingid=b.filingid;quit;
data dxbrl.final; set sample6; run;

data dxbrl.elements; set elements;run;
**Transpose elements table - to prepare for merging with fdetail2;
proc sort data=dxbrl.elements; by element_id;run;
proc transpose data=dxbrl.elements (drop=numobs) out=elements2;
	by element_id element_name std_element;	var fn_tax_n--fn_qtr_w;run;	
data elements2; set elements2; rename _name_=footnote;run;
	*Mark any with no categories as other, renaming the first one (fn_cc_n);
proc sql; create table elements3
	as select distinct *, sum(col1) as totalcategories, prxchange('s/(.*?)_(.*?)_(.*)/$2/',1,footnote) as footnote_type,
		prxchange('s/(.*?)_(.*?)_(.*)/$3/',1,footnote) as footnote_type_precision
	from elements2 group by element_id, element_name;quit;
proc sql; alter table elements3 modify footnote_type char(10) format=$10. modify footnote_type_precision char(2) format=$2.;quit;
data elements3; set elements3; if totalcategories=0 and footnote="fn_cc_n" then do;
		footnote="fn_other_w"; col1=1; totalcategories=totalcategories+1; footnote_type="other"; footnote_type_precision="w"; end; run;
data elements3 (drop=col1); set elements3; where col1=1;run;
	*Identifying dual classified elements;
proc sql; create table elements4 as select distinct *, count(distinct footnote_type) as numtypes
	from elements3 group by element_id order by element_id, numtypes desc;quit;
data test; set elements4; where numtypes>1;run;
proc sql; create table test2 as select distinct footnote_type from elements4;quit;
	*Assigning dual classified elements to one, based on footnote_type rank and footnote_type_precision;
proc sql; create table elements5 as select distinct a.*, b.rank
	from elements3 as a left join dxbrl.element_typerank as b on a.footnote_type=b.footnote_type;quit;
proc sort data=elements5; by element_id footnote_type_precision rank;run;
proc sort data=elements5 nodupkey; by element_id;run;
	*Summarizing number of tags by footnote classification - merge with fdetail;
proc sql; create table fdetail3	as select a.*, b.footnote_type, b.footnote_type_precision
	from fdetail as a left join elements5 as b on a.element_name=b.element_name and a.std_element=b.std_element;quit;

proc sql;create table notes2
	as select distinct filingid, footnote_type, count(num_tags_footnote) as num_notes_pertype,
		sum(num_tags_footnote) as num_tags_footnote, sum(num_words_footnote) as num_words_footnote,
		max(num_tags_footnote) as num_tags_footnote_max, max(num_words_footnote) as num_words_footnote_max
	from fdetail3 group by filingid, footnote_type;quit;
*Transpose back again and then merge with fdetail2;
proc transpose data=notes2 out=notes21 prefix=tagsa_;
	by filingid; id footnote_type; var num_tags_footnote;run;
proc transpose data=notes2 out=notes22 prefix=wordsa_;
	by filingid; id footnote_type; var num_words_footnote;run;
data wide2; merge notes21 (drop= _name_) notes22 (drop= _name_);run;
	*Fill in missing fields with zero;
data wide2;	set wide2; array zero tagsa_cc--wordsa_vie;	do over zero; if zero=. then zero=0;end; run;
**Merging fields with totals back into original sample;
*First capturing total tags per firm;
proc sql; create table fdetail2
	as select distinct filingid, count(std_element) as num_footnotes, sum(std_element) as num_footnotes_std,
		sum(num_tags_footnote) as num_tags_notes_total, sum(num_words_footnote) as num_words_notes_total
	from fdetail group by filingid order by filingid, num_footnotes_std, num_tags_notes_total, num_words_notes_total;quit;
***************************************************************;
**Final merge;
proc sql; create table dxbrl.final2	as select distinct a.*, b.*, c.*
	from (dxbrl.final as a left join fdetail2 as b on a.filingid=b.filingid) left join wide2 as c on a.filingid=c.filingid;quit;
